-- FitMarket AI: carga inicial del catálogo de alimentos (public.foods).
-- GENERADO por scripts/foods/build-seed.ts a partir de data/foods/foods.json.
-- No editar a mano: cambia el JSON y vuelve a generar.
-- Nutrición ampliada: USDA FoodData Central (dominio público) y Open Food Facts (ODbL).
-- Ver docs/DATA_SOURCES.md. Idempotente: se puede ejecutar más de una vez.

on conflict (id) do update set
  name_es = excluded.name_es,
  name_en = excluded.name_en,
  plural_es = excluded.plural_es,
  plural_en = excluded.plural_en,
  shopping_category = excluded.shopping_category,
  unit = excluded.unit,
  whole_units = excluded.whole_units,
  grams_per_unit = excluded.grams_per_unit,
  diet_tags = excluded.diet_tags,
  kcal = excluded.kcal,
  protein_g = excluded.protein_g,
  carbs_g = excluded.carbs_g,
  fat_g = excluded.fat_g,
  fiber_g = excluded.fiber_g,
  free_sugars_g = excluded.free_sugars_g,
  sat_fat_g = excluded.sat_fat_g,
  sodium_mg = excluded.sodium_mg,
  iron_mg = excluded.iron_mg,
  gaba_group = excluded.gaba_group,
  is_fruit_veg = excluded.is_fruit_veg,
  default_pack = excluded.default_pack,
  ref_price_cop = excluded.ref_price_cop,
  ref_price_source = excluded.ref_price_source,
  nutrition_source = excluded.nutrition_source,
  nutrition_ref = excluded.nutrition_ref;
